mapper.select:
SELECT co.clubOwner_key FROM member1 m
JOIN clubOwner co ON m.memberIdx = co.memberIdx
WHERE m.memberIdx = #{memberIdx}

mapper.update:
UPDATE clubMatchBoard
SET cmb_HitCount = NVL(cmb_HitCount, 0) + 1
WHERE cmb_num = #{cmb_num}

mapper.select:
        SELECT r.cmb_num, r.clubJoin_num, r.request_date,
            r.request_state, r.request_intro, r.reject_reason
        FROM clubMatchRequest r
        
        INNER JOIN clubJoin cj ON r.clubJoin_num = cj.clubJoin_num
        WHERE r.cmb_num = #{cmb_num}
        AND cj.memberIdx = #{memberIdx}

mapper.update:
	UPDATE clubMatchRequest
	SET request_state = -1, request_cancel = #{request_cancel}
    WHERE cmb_num = #{cmb_num} AND clubJoin_num = #{clubJoin_num}

        UPDATE clubMatchRequest r
        SET r.request_state = 1, r.reject_reason = NULL

        WHERE r.cmb_num = #{cmb_num}
        AND r.clubJoin_num = #{clubJoin_num}

        AND EXISTS (
            SELECT 1
            FROM clubMatchBoard b
            INNER JOIN clubOwner o
                ON b.clubOwner_key = o.clubOwner_key
            WHERE b.cmb_num = r.cmb_num
            AND o.memberIdx = #{memberIdx}
        )

        UPDATE clubMatchRequest r
        SET
            r.request_state = 0,
            r.reject_reason = #{reject_reason}
        WHERE r.cmb_num = #{cmb_num}
        AND r.clubJoin_num = #{clubJoin_num}

        AND EXISTS (
            SELECT 1
            FROM clubMatchBoard b
            INNER JOIN clubOwner o
                ON b.clubOwner_key = o.clubOwner_key
            WHERE b.cmb_num = r.cmb_num
            AND o.memberIdx = #{memberIdx}
        )

        UPDATE Match_Apply a
        SET
            a.status = 0,
            a.cancel_reason = #{cancel_reason}

        WHERE a.cmb_num = #{cmb_num}

        AND EXISTS (
            SELECT 1
            FROM clubMatchBoard b
            INNER JOIN clubOwner o
                ON b.clubOwner_key = o.clubOwner_key
            WHERE b.cmb_num = a.cmb_num
            AND o.memberIdx = #{memberIdx}
        )
